const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/temporal";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "package.json"), JSON.stringify({ type: "module" }));
// A minimal global Temporal (Now + Instant), as a polyfill or Node.js >= 26 would provide.
fs.writeFileSync(path.join(dir, "temporal.test.mjs"), [
  "import { test, vi } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "const realNow = Date.now",
  "globalThis.Temporal = {",
  "  Now: { instant: () => ({ epochMilliseconds: realNow() }), timeZoneId: () => 'UTC' },",
  "  Instant: { fromEpochNanoseconds: (ns) => ({ epochMilliseconds: Number(ns / 1000000n) }) },",
  "}",
  "test('temporal', () => {",
  "  vi.useFakeTimers()",
  "  vi.setSystemTime(1000)",
  "  const temporal = Temporal.Now.instant().epochMilliseconds",
  "  const date = Date.now()",
  "  vi.useRealTimers()",
  "  writeFileSync(new URL('./result.json', import.meta.url), JSON.stringify({ temporal, date }))",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const resultFile = path.join(dir, "result.json");
if (!fs.existsSync(resultFile)) {
  console.error("ERROR: the test wrote no result (exit " + r.status + ")");
  process.exit(2);
}
const res = JSON.parse(fs.readFileSync(resultFile, "utf8"));
console.log(JSON.stringify(res));
if (res.date !== 1000) {
  console.error("ERROR: fake Date.now() returned " + res.date + ", expected 1000");
  process.exit(2);
}
if (res.temporal === 1000) {
  console.log("PASS: Temporal.Now.instant() follows the fake clock (1000)");
  process.exit(0);
}
if (typeof res.temporal === "number" && Math.abs(res.temporal - Date.now()) < 120000) {
  console.error("FAIL: Temporal.Now.instant() returned the real time under vi.useFakeTimers()");
  process.exit(1);
}
console.error("ERROR: unexpected Temporal value " + res.temporal);
process.exit(2);

